<source_code>
#include <bits/stdc++.h>
using namespace std;
#define int long long

const int N = 507;

int n, m, p;
int fac[N], ifac[N];
int f[N][N], g[N][N];
int dp[N][N], sum_dp[N][N];

inline int pows(long long u, int v) {
    long long ans = 1;
    while (v > 0) {
        if (v & 1) ans = ans * u % p;
        u = u * u % p;
        v >>= 1;
    }
    return ans;
}

inline int binom(int a, int b) {
    if (a < b) return 0;
    return 1ll * fac[a] % p * ifac[b] % p * ifac[a - b] % p;
}

inline int getsum(int u) {
    return u * (u + 1) / 2;
}

signed main() {
    cin >> n >> m >> p;
    fac[0] = ifac[0] = 1;
    for (int i = 1; i <= 500; i++) {
        fac[i] = 1ll * fac[i - 1] * i % p;
        ifac[i] = pows(fac[i], p - 2);
    }

    // Initialize DP for intervals
    for (int len = 1; len <= n; len++) {
        for (int l = 1; l <= n; l++) {
            int r = l + len - 1;
            if (r > n) continue;

            if (l == r) {
                f[l][r] = 0;
                g[l][r] = 2; // Two ways: L and R
            } else {
                // Case 1: First person sits at position l (enters from left)
                f[l][r] = (f[l][r] + f[l + 1][r] + g[l + 1][r] * (l - l)) % p;
                g[l][r] = (g[l][r] + g[l + 1][r]) % p;

                // Case 2: First person sits at position r (enters from right)
                f[l][r] = (f[l][r] + f[l][r - 1] + g[l][r - 1] * (r - r)) % p;
                g[l][r] = (g[l][r] + g[l][r - 1]) % p;

                // Case 3: First person sits at position x (l < x < r)
                for (int x = l + 1; x < r; x++) {
                    // Left part: [l, x-1], Right part: [x+1, r]
                    int left_len = x - l;
                    int right_len = r - x;
                    int total_len = r - l;

                    // The first person sits at x
                    // Left participants: choose left_len positions from total_len
                    // Right participants: choose right_len positions from total_len

                    // Contribution from left and right parts
                    f[l][r] = (f[l][r] + 
                               f[l][x - 1] * g[x + 1][r] % p +
                               f[x + 1][r] * g[l][x - 1] % p) % p;

                    // Contribution from the distance for the first person
                    f[l][r] = (f[l][r] + 
                               (getsum(left_len) + getsum(right_len)) % p * 
                               g[l][x - 1] % p * g[x + 1][r] % p) % p;

                    // Total ways
                    g[l][r] = (g[l][r] + 
                               g[l][x - 1] * g[x + 1][r] % p * binom(total_len, left_len) % p) % p;
                }
            }
        }
    }

    // DP for the whole problem
    dp[0][0] = 0;
    sum_dp[0][0] = 1;

    for (int i = 1; i <= n; i++) {
        for (int j = i; j <= n; j++) {
            int len = j - i + 1;
            for (int k = 0; k <= m; k++) {
                if (k + len > m) continue;

                // Add contribution of interval [i, j]
                dp[j][k + len] = (dp[j][k + len] + 
                                  dp[i - 1][k] * g[i][j] % p * binom(k + len, len) % p +
                                  sum_dp[i - 1][k] * f[i][j] % p * binom(k + len, len) % p) % p;

                sum_dp[j][k + len] = (sum_dp[j][k + len] + 
                                      sum_dp[i - 1][k] * g[i][j] % p * binom(k + len, len) % p) % p;
            }
        }

        // Prefix sums
        for (int k = 0; k <= m; k++) {
            dp[i][k] = (dp[i][k] + dp[i - 1][k]) % p;
            sum_dp[i][k] = (sum_dp[i][k] + sum_dp[i - 1][k]) % p;
        }
    }

    cout << (dp[n][m] + sum_dp[n][m]) % p << endl;
}
</source_code>
